+          borderRadius: "4px",
+          outline: "none",
+          fontFamily: "monospace",
+          fontSize: "13px",
+        }}
+      />
+      <select
+        value={envId}
+        onChange={(e) => setEnvId(e.target.value)}
+        style={{
+          background: "#0f3460",
+          border: "1px solid #333",
+          color: "#e0e0e0",
+          padding: "6px 8px",
+          borderRadius: "4px",
+          fontFamily: "monospace",
+          fontSize: "12px",
+        }}
