+            '[' | ']' => {} // strip brackets (contents become literal)
+            c if ".+^${}()|\\".contains(c) => {
+                has_literal = true;
+                pat.push('\\');
+                pat.push(c);
+            }
+            c => {
+                has_literal = true;
+                pat.push(c);
+            }
+        }
+    }
+    if !has_literal {
+        return None;
+    }
+    Regex::new(&pat).ok()
