+    const result = redactHeaders({
+      'x-n8n-key': 'per-tenant-api-key',
+      'x-n8n-url': 'https://tenant.internal/',
+    });
+    expect(result['x-n8n-key']).toBe(REDACTED);
+    expect(result['x-n8n-url']).toBe(REDACTED);
+  });
